class ObatData extends DataClass implements Insertable<ObatData> {
  final int id;
  final String nama;
  final String? dosisTeks;
  final int jumlahPerMinum;

  /// tablet / kapsul / ml / tetes / sachet / lain.
  final String satuan;
  final DateTime? mulai;
  final DateTime? selesai;
  final bool aktif;
  final String? catatan;
  final DateTime dibuatPada;
  final DateTime diubahPada;

  /// FR-107: sisa obat di rumah (dalam satuan di atas). null = belum diisi.
  final int? sisa;
  final DateTime? sisaDiperbaruiPada;
  const ObatData({
    required this.id,
    required this.nama,
    this.dosisTeks,
    required this.jumlahPerMinum,
    required this.satuan,
    this.mulai,
    this.selesai,
    required this.aktif,
    this.catatan,
    required this.dibuatPada,
    required this.diubahPada,
    this.sisa,
    this.sisaDiperbaruiPada,
