          ? const Value.absent()
          : Value(berkasNama),
      catatan: catatan == null && nullToAbsent
          ? const Value.absent()
          : Value(catatan),
      leadHari: Value(leadHari),
      kanalPengingat: Value(kanalPengingat),
      aktif: Value(aktif),
      arsip: Value(arsip),
      diperpanjangPada: diperpanjangPada == null && nullToAbsent
